blocks.code:
h1 {
  color: #2563eb;
  font-family: system-ui, sans-serif;
}

.lead {
  font-size: 20px;
  font-weight: 600;
  color: #0f172a;
}

p {
  color: #475569;
  line-height: 1.6;
}

.box {
  background: #dbeafe;
  border: 3px solid #2563eb;
  padding: 16px;      /* воздух внутри */
  margin: 12px;       /* отступ снаружи */
  width: 200px;
}

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  background: #f1f5f9;
  padding: 12px;
}

.item {
  background: #2563eb;
  color: #fff;
  padding: 18px 26px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

tasks.tests:
equal(style('h1', 'color'), 'rgb(255, 0, 0)', 'Цвет заголовка');
equal(style($$('p')[0], 'font-size'), '20px', 'Размер шрифта абзаца');
equal(style($$('p')[1], 'font-size'), '20px', 'Размер шрифта у всех абзацев');

var c = $('.card');
assert(c, 'Не найден элемент с классом card');
equal(style(c, 'padding-top'), '16px', 'Внутренний отступ');
equal(style(c, 'border-top-width'), '2px', 'Толщина рамки');
equal(style(c, 'border-top-style'), 'solid', 'Стиль рамки');
equal(style(c, 'border-top-color'), 'rgb(0, 0, 255)', 'Цвет рамки');
equal(style(c, 'border-top-left-radius'), '8px', 'Скругление');
equal(style(c, 'box-sizing'), 'border-box', 'box-sizing');

var h = $('.header');
assert(h, 'Не найден .header');
equal(style(h, 'display'), 'flex', 'display');
equal(style(h, 'justify-content'), 'space-between', 'justify-content');
equal(style(h, 'align-items'), 'center', 'align-items');
assert(style(h, 'gap').indexOf('10px') === 0, 'gap должен быть 10px, а сейчас: ' + style(h, 'gap'));

var b = $('.btn');
assert(b, 'Не найден .btn');
equal(style(b, 'color'), 'rgb(255, 255, 255)', 'Цвет текста');
equal(style(b, 'background-color'), 'rgb(37, 99, 235)', 'Цвет фона');
equal(style(b, 'padding-top'), '12px', 'Отступы');
equal(style(b, 'border-top-left-radius'), '6px', 'Скругление');
equal(style(b, 'cursor'), 'pointer', 'Курсор');

blocks.code:
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
}

.cell {
  background: #e0f2fe;
  border: 1px solid #38bdf8;
  padding: 18px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

.wide {
  grid-column: span 2;   /* ячейка на две колонки */
  background: #bae6fd;
}

/* база — для узкого экрана */
.cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

/* добавляем на широком */
@media (min-width: 700px) {
  .cards { grid-template-columns: repeat(3, 1fr); }
}

.card {
  background: #dcfce7;
  border: 1px solid #22c55e;
  padding: 16px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}
.hint { font: 14px system-ui; color: #64748b; }

:root {
  --brand: #2563eb;
  --radius: 10px;
}

.btn {
  background: var(--brand);
  color: #fff;
  border: 0;
  padding: 12px 20px;
  border-radius: var(--radius);
  font: 15px system-ui;
  cursor: pointer;
  transition: background .2s, transform .2s;
}

.btn:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
}

.panel {
  margin-top: 16px;
  padding: 18px;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: 0 4px 14px rgba(15, 23, 42, .12);
  font: 15px system-ui;
}

tasks.tests:
const g = $('.gallery');
assert(g, 'Не найден .gallery');
equal(style(g, 'display'), 'grid', 'display');
const cols = style(g, 'grid-template-columns').split(' ').filter(Boolean);
equal(cols.length, 3, 'Количество колонок');
assert(style(g, 'gap').indexOf('12px') === 0, 'gap должен быть 12px, а сейчас: ' + style(g, 'gap'));

const t = $('.tag');
assert(t, 'Не найден .tag');
equal(style(t, 'background-color'), 'rgb(22, 163, 74)', 'Фон должен прийти из переменной');
equal(style(t, 'color'), 'rgb(255, 255, 255)', 'Цвет текста');
const rootVar = getComputedStyle(document.documentElement).getPropertyValue('--main').trim();
assert(rootVar.length > 0, 'Переменная --main должна быть объявлена в :root');

const c = $('.cta');
assert(c, 'Не найден .cta');
equal(style(c, 'background-color'), 'rgb(124, 58, 237)', 'Фон');
equal(style(c, 'border-top-left-radius'), '8px', 'Скругление');
equal(style(c, 'transition-duration'), '0.3s', 'Длительность перехода');
equal(style(c, 'transition-property'), 'all', 'Переход применён ко всем свойствам');

const l = $('.list');
assert(l, 'Не найден .list');
equal(style(l, 'display'), 'grid', 'display');
assert(style(l, 'gap').indexOf('16px') === 0, 'gap должен быть 16px, а сейчас: ' + style(l, 'gap'));
const cols = style(l, 'grid-template-columns').split(' ').filter(Boolean);
equal(cols.length, 2, 'На широком экране должно быть две колонки');
